return {["scripts/actions/abilities/bully.lua"]={["Path"]="scripts/actions/abilities/bully.lua",["SHA256"]="5224f34b3dfa34a496e72e8f5072f6f8f873fa0baf305b3b56a4d4805697047d",["Text"]="-----------------------------------\n-- Ability: Bully\n-- Intimidates target. (About 15% proc rate)\n-- Removes the direction requirement from Sneak Attack for main job Thieves when active.\n-- Obtained: Thief Level 93\n-- Recast Time: 3:00\n-- Duration: 0:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.thief.useBully(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/burst_affinity.lua"]={["Path"]="scripts/actions/abilities/burst_affinity.lua",["SHA256"]="444cf2c1ec07ac8ada53a0865f72124078d4d030fef1a630d92ca87f2627eb09",["Text"]="-----------------------------------\n-- Ability: Burst Affinity\n-- Makes it possible for your next \"magical\" blue magic spell to be used in a Magic Burst.\n-- Obtained: Blue Mage Level 25\n-- Recast Time: 2 minutes\n-- Duration: 30 seconds\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    xi.job_utils.blue_mage.checkBurstAffinity(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.blue_mage.useBurstAffinity(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/call_beast.lua"]={["Path"]="scripts/actions/abilities/call_beast.lua",["SHA256"]="5a6583105ca6b5f8235d11d4548d5bde93f6df2c525c14e3a930b69b872b712c",["Text"]="-----------------------------------\n-- Ability: Call Beast\n-- Calls a beast to fight by your side.\n-- Obtained: Beastmaster Level 23\n-- Recast Time: 5:00\n-- Duration: Dependent on jug pet used.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.beastmaster.checkCallBeast(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.beastmaster.useCallBeast(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/call_wyvern.lua"]={["Path"]="scripts/actions/abilities/call_wyvern.lua",["SHA256"]="ead140b38d00be1d3c075a15eee6ed7698121eab6252ef95c1b2665c43f0e963",["Text"]="-----------------------------------\n-- Ability: Call Wyvern\n-- Summons a Wyvern to fight by your side.\n-- Obtained: Dragoon Level 1\n-- Recast Time: 20:00\n-- Duration: Instant\n-- Special: Only available if Dragoon is your main class.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dragoon.abilityCheckCallWyvern(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    xi.job_utils.dragoon.useCallWyvern(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/camouflage.lua"]={["Path"]="scripts/actions/abilities/camouflage.lua",["SHA256"]="013f46bc124ca4ea253948ace1cd2c6277377b51474538ff6a17f795d3e3bbb6",["Text"]="-----------------------------------\n-- Ability: Camouflage\n-- Become hidden from enemies.\n-- Obtained: Ranger Level 20\n-- Recast Time: 5:00\n-- Duration: Random\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.ranger.checkCamouflage(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.ranger.useCamouflage(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/caper_emissarius.lua"]={["Path"]="scripts/actions/abilities/caper_emissarius.lua",["SHA256"]="2e658a17fd8f58e45bb9b91884dbf218c9a7c499bbe1f8c1497f2e8a3ed19f50",["Text"]="-----------------------------------\n-- Ability: Caper Emissarius\n-- Description: Transfers enmity to a party member of your choice.\n-- Obtained: SCH Level 96\n-- Recast Time: 01:00:00\n-- Duration: 00:00:30\n-- target:transferEnmity(player, 99, 20.6)\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if target == nil or target:getID() == player:getID() or not target:isPC() then\n        return xi.msg.basic.CANNOT_ON_THAT_TARG, 0\n    end\n\n    ability:setRecast(math.max(0, ability:getRecast() - player:getMod(xi.mod.ONE_HOUR_RECAST) * 60))\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    target:transferEnmity(player, 99, 20.6)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/cascade.lua"]={["Path"]="scripts/actions/abilities/cascade.lua",["SHA256"]="b72a68527c2a27068e869df886c14b8f40031b893d26da95f240a4beeff11715",["Text"]="-----------------------------------\n-- Ability: Cascade\n-- Description: Grants a damage bonus to the next elemental magic spell cast based on TP consumed.\n-- Obtained: BLM Level 85\n-- Recast Time: 00:01:00\n-- Duration: 0:01:00 or the next spell cast\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.black_mage.useCascade(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/casters_roll.lua"]={["Path"]="scripts/actions/abilities/casters_roll.lua",["SHA256"]="60fb752bf4c1c8b79e9ef410332c10e57d55bda067c46c640975b9a8dc779e44",["Text"]="-----------------------------------\n-- Ability: Caster's Roll\n-- Enhances \"Fast Cast\" effect for party members within area of effect.\n-- Optimal Job: None\n-- Lucky Number: 2\n-- Unlucky Number: 7\n-- Level: 79\n-- Phantom Roll +1 Value: 3\n--\n-- Die Roll    | Fast Cast%\n-- --------    -------\n-- 1           |+6\n-- 2           |+15\n-- 3           |+7\n-- 4           |+8\n-- 5           |+9\n-- 6           |+10\n-- 7           |+5\n-- 8           |+11\n-- 9           |+12\n-- 10          |+13\n-- 11          |+20\n-- Bust        |-10\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/celerity.lua"]={["Path"]="scripts/actions/abilities/celerity.lua",["SHA256"]="0f42088460845d89f104d45d24a3716ab991f2a2fa49df9af47f6969a551cc01",["Text"]="-----------------------------------\n-- Ability: Celerity\n-- Reduces the casting time and the recast time of your next white magic spell by 50%.\n-- Obtained: Scholar Level 25\n-- Recast Time: Stratagem Charge\n-- Duration: 1 white magic spell or 60 seconds, whichever occurs first.\n--\n-- Level   |Charges |Recharge Time per Charge\n-- -----   -------- ---------------\n-- 10      |1       |4:00 minutes\n-- 30      |2       |2:00 minutes\n-- 50      |3       |1:20 minutes\n-- 70      |4       |1:00 minute\n-- 90      |5       |48 seconds\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.CELERITY) then\n        return xi.msg.basic.EFFECT_ALREADY_ACTIVE, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.CELERITY, { power = 1, duration = 60, origin = player })\n\n    return xi.effect.CELERITY\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/chain_affinity.lua"]={["Path"]="scripts/actions/abilities/chain_affinity.lua",["SHA256"]="1d26cb54f260dcffbb761d79c53c6be8a7d5180baadaa41e885f87329bac693d",["Text"]="-----------------------------------\n-- Ability: Chain Affinity\n-- Makes it possible for your next \"physical\" blue magic spell to be used in a skillchain. Effect varies with TP.\n-- Obtained: Blue Mage Level 40\n-- Recast Time: 2 minutes\n-- Duration: 30 seconds or one Blue Magic spell\n-- May be used with Sneak Attack and Trick Attack.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    xi.job_utils.blue_mage.checkChainAffinity(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.blue_mage.useChainAffinity(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/chainspell.lua"]={["Path"]="scripts/actions/abilities/chainspell.lua",["SHA256"]="7d5f4ec16c7ee599d45a3c0327488daa640e3eb46790b6f67c482c1d8f3af75f",["Text"]="-----------------------------------\n-- Ability: Chainspell\n-- Allows rapid spellcasting.\n-- Obtained: Red Mage Level 1\n-- Recast Time: 1:00:00\n-- Duration: 0:01:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.red_mage.checkChainspell(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.red_mage.useChainspell(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/chakra.lua"]={["Path"]="scripts/actions/abilities/chakra.lua",["SHA256"]="92096eb453b39bdc3fd970944a7f11b134f6e434f68080e97e3dc8e1978d0ec1",["Text"]="-----------------------------------\n-- Ability: Chakra\n-- Cures certain status effects and restores a small amount of HP to user.\n-- Obtained: Monk Level 35\n-- Recast Time: 5:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.monk.useChakra(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/chaos_roll.lua"]={["Path"]="scripts/actions/abilities/chaos_roll.lua",["SHA256"]="00d3f4ff03ec26d94104d031ffbf5635687871e9afa685d819d7c0e250012c03",["Text"]="-----------------------------------\n-- Ability: Chaos Roll\n-- Enhances attack for party members within area of effect\n-- Optimal Job: Dark Knight\n-- Lucky Number: 4\n-- Unlucky Number: 8\n-- Level: 14\n-- Phantom Roll +1 Value: 3\n--\n-- Die Roll    |No DRK    |With DRK\n-- --------    -------- -----------\n-- 1           |6%      |16%\n-- 2           |8%      |18%\n-- 3           |9%      |19%\n-- 4           |25%     |35%\n-- 5           |11%     |21%\n-- 6           |13%     |23%\n-- 7           |16%     |26%\n-- 8           |3%      |13%\n-- 9           |17%     |27%\n-- 10          |19%     |29%\n-- 11          |31%     |41%\n-- Bust        |-10%    |-10%\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/charm.lua"]={["Path"]="scripts/actions/abilities/charm.lua",["SHA256"]="b47ca51637ff99901fdac7b224657f318fdcfe947778660eb5a60f946cf565f5",["Text"]="-----------------------------------\n-- Ability: Charm a monster\n-- Tames a monster to fight by your side.\n-- Obtained: Beastmaster Level 1\n-- Recast Time: 0:15\n-- Duration: Varies\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.beastmaster.checkCharm(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.beastmaster.useCharm(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/chi_blast.lua"]={["Path"]="scripts/actions/abilities/chi_blast.lua",["SHA256"]="5f0b09af7ae6703cf245f444b4972d978bff6140e5494b4bb26f0a7b1b9a5724",["Text"]="-----------------------------------\n-- Ability: Chi Blast\n-- Releases Chi to attack an enemy.\n-- Obtained: Monk Level 41\n-- Recast Time: 3:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.monk.useChiBlast(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/chivalry.lua"]={["Path"]="scripts/actions/abilities/chivalry.lua",["SHA256"]="28b0a9e5261d70069014764ff8eca081b754f89ceaa5d224bbc331aacc5ba55c",["Text"]="-----------------------------------\n-- Ability: Chivalry\n-- Converts TP to MP.\n-- Obtained: Paladin Level 75 (Must be Purchased with Merit Points)\n-- Recast Time: 0:10:00 (+5% MP granted per additional upgrade)\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.paladin.useChivalry(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/chocobo_jig.lua"]={["Path"]="scripts/actions/abilities/chocobo_jig.lua",["SHA256"]="36c0b17f299acd2b2101ddf5d68aa98f36f50a170f3fc46aa8e9a48b2477d49f",["Text"]="-----------------------------------\n-- Ability: Chocobo jig\n-- Increases Movement Speed.\n-- Obtained: Dancer Level 55\n-- TP Required: 0\n-- Recast Time: 1:00\n-- Duration: 2:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    local baseDuration       = 120 + player:getJobPointLevel(xi.jp.JIG_DURATION)\n    local durationMultiplier = 1.0 + utils.clamp(player:getMod(xi.mod.JIG_DURATION), 0, 50) / 100\n    local finalDuration      = math.floor(baseDuration * durationMultiplier)\n\n    -- TODO: Chocobo Jig will not override all types of weight effect. Find out which aren't overriden.\n    if player:hasStatusEffect(xi.effect.WEIGHT) then\n        player:delStatusEffect(xi.effect.WEIGHT)\n    end\n\n    player:addStatusEffect(xi.effect.QUICKENING, { power = 10, duration = finalDuration, origin = player })\n\n    return xi.effect.QUICKENING\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/chocobo_jig_ii.lua"]={["Path"]="scripts/actions/abilities/chocobo_jig_ii.lua",["SHA256"]="23390f39b8ef9996061a33315f897b555bedde0a8d01c56400f9d7ac10ed1407",["Text"]="-----------------------------------\n-- Ability: Chocobo jig ii\n-- Increases Movement Speed to party members within the area of effect.\n-- Obtained: Dancer Level 70\n-- TP Required: 0\n-- Recast Time: 1:00\n-- Duration: 2:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    local baseDuration       = 120 + player:getJobPointLevel(xi.jp.JIG_DURATION)\n    local durationMultiplier = 1.0 + utils.clamp(player:getMod(xi.mod.JIG_DURATION), 0, 50) / 100\n    local finalDuration      = math.floor(baseDuration * durationMultiplier)\n\n    -- TODO: Chocobo Jig will not override all types of weight effect. Find out which aren't overriden.\n    if target:hasStatusEffect(xi.effect.WEIGHT) then\n        target:delStatusEffect(xi.effect.WEIGHT)\n    end\n\n    target:addStatusEffect(xi.effect.QUICKENING, { power = 10, duration = finalDuration, origin = player })\n\n    return xi.effect.QUICKENING\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/choral_roll.lua"]={["Path"]="scripts/actions/abilities/choral_roll.lua",["SHA256"]="348791b729c985907f289efc51190fabb3c21930c2bb340de49a15f1fca5cc68",["Text"]="-----------------------------------\n-- Ability: Choral Roll\n-- Decreases spell interruption rate for party members within area of effect\n-- Optimal Job: Bard\n-- Lucky Number: 2\n-- Unlucky Number: 6\n-- Level: 26\n-- Phantom Roll +1 Value: 4\n--\n-- Die Roll     |No BRD     |With BRD\n-- --------     --------    -------\n-- 1            |-8         |-33\n-- 2            |-42        |-67\n-- 3            |-11        |-36\n-- 4            |-15        |-40\n-- 5            |-19        |-44\n-- 6            |-4         |-29\n-- 7            |-23        |-48\n-- 8            |-27        |-52\n-- 9            |-31        |-56\n-- 10           |-35        |-60\n-- 11           |-50        |-75\n-- Bust         |+25        |+25\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/clarion_call.lua"]={["Path"]="scripts/actions/abilities/clarion_call.lua",["SHA256"]="904c4da3c9ea54caf50f194d52d36cf72d3b8adbbef3fbdcb153c29e86d3de8b",["Text"]="-----------------------------------\n-- Ability: Clarion Call\n-- Description: Increases the number of songs that can affect party members by one.\n-- Obtained: BRD Level 96\n-- Recast Time: 01:00:00\n-- Duration: 0:03:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.bard.checkClarionCall(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.bard.useClarionCall(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/climactic_flourish.lua"]={["Path"]="scripts/actions/abilities/climactic_flourish.lua",["SHA256"]="bc4e4bf4fafb6c77264444aa718c298dcb07a11570d8831d909f581d2fcf3fb5",["Text"]="-----------------------------------\n-- Ability: Climactic Flourish\n-- Description: Allows you to deal critical hits. Requires at least one finishing move.\n-- Obtained: DNC Level 80\n-- Recast Time: 00:01:30 (Flourishes III)\n-- Duration: 00:01:00\n-- Cost: 1-5 Finishing Move charges\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if\n        player:hasStatusEffect(xi.effect.FINISHING_MOVE_1) or\n        player:hasStatusEffect(xi.effect.FINISHING_MOVE_2) or\n        player:hasStatusEffect(xi.effect.FINISHING_MOVE_3) or\n        player:hasStatusEffect(xi.effect.FINISHING_MOVE_4) or\n        player:hasStatusEffect(xi.effect.FINISHING_MOVE_5)\n    then\n        return 0, 0\n    end\n\n    return xi.msg.basic.NO_FINISHINGMOVES, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    for move = xi.effect.FINISHING_MOVE_1, xi.effect.FINISHING_MOVE_5 do\n        player:delStatusEffect(move)\n        player:addStatusEffect(xi.effect.CLIMACTIC_FLOURISH, { power = 3, duration = 60, origin = player }) -- TODO: player:getMerit(xi.merit.CLIMACTIC_FLOURISH_EFFECT) This was here and maybe it refered to FLOURISH_III job points?\n    end\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/collaborator.lua"]={["Path"]="scripts/actions/abilities/collaborator.lua",["SHA256"]="2db4a32d42c08b49cfba8eab6f2f82fd347f6f6bb85b64b8f45324b62d833d14",["Text"]="-----------------------------------\n-- Ability: Collaborator\n-- Steals 25% of the target party member's enmity and redirects it to the thief.\n-- Obtained: Thief Level 65\n-- Recast Time: 1:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.thief.checkCollaborator(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    xi.job_utils.thief.useCollaborator(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/companions_roll.lua"]={["Path"]="scripts/actions/abilities/companions_roll.lua",["SHA256"]="94eaaba5b36fc5afae8c845929604156024f550052d437031bb6e7fcd9625cc6",["Text"]="-----------------------------------\n-- Ability: Companion's Roll\n-- Grants \"Regain\" and \"Regen\" effects to pets of party members within area of effect.\n-- Optimal Job: None\n-- Lucky Number: 2\n-- Unlucky Number: 10\n-- Level: 95\n-- Phantom Roll +1 Value: 5/2\n--\n-- Die Roll Logic in globals/effects/companions_roll.lua\n--\n-- Die Roll    | Regain | Regen\n-- --------    -------   -------\n-- 1           |+20     |+4\n-- 2           |+50     |+20\n-- 3           |+20     |+6\n-- 4           |+20     |+8\n-- 5           |+30     |+10\n-- 6           |+30     |+12\n-- 7           |+30     |+14\n-- 8           |+40     |+16\n-- 9           |+40     |+18\n-- 10          |+10     |+3\n-- 11          |+60     |+25\n-- Bust        |-0      | 0\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/composure.lua"]={["Path"]="scripts/actions/abilities/composure.lua",["SHA256"]="9e52e7040ba65067fb55b4e6ba52122ed3ae6ee3b7218736ebad54f6473a9aa4",["Text"]="-----------------------------------\n-- Ability: Composure\n-- Increases accuracy and lengthens recast time. Enhancement effects gained through white and black magic you cast on yourself last longer.\n-- Obtained: Red Mage Level 50\n-- Recast Time: 5:00\n-- Duration: 120 minutes\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.red_mage.useComposure(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/conspirator.lua"]={["Path"]="scripts/actions/abilities/conspirator.lua",["SHA256"]="399525987510816eb3bfd08fca6958d51f1b77a74a9e1c08fe3012df178eb508",["Text"]="-----------------------------------\n-- Ability: Conspirator\n-- Enhances accuracy and \"Subtle Blow\" effect for party members within area of effect.\n-- Does not affect the party member being targeted by the enemy.\n-- Obtained: Thief Level 87\n-- Recast Time: 5:00\n-- Duration: 1:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.thief.useConspirator(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/consume_mana.lua"]={["Path"]="scripts/actions/abilities/consume_mana.lua",["SHA256"]="f5c1dfaa15e12b3fa090c6b97ece0c073348ce763dbd8d466956f38fafa90c01",["Text"]="-----------------------------------\n-- Ability: Consume Mana\n-- Description: Converts all MP into damage for the next attack.\n-- Obtained: Dark Knight Level 55\n-- Recast Time: 00:01:00 (or next attack)\n-- Duration: 00:01:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.dark_knight.useConsumeMana(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/contradance.lua"]={["Path"]="scripts/actions/abilities/contradance.lua",["SHA256"]="13a22fcdb5a7ed61eb58741cd01ce2c1fa1b0cbc99c91df7ddc29bde2b5fbc5c",["Text"]="-----------------------------------\n-- Ability: Contradance\n-- Description: Increases the amount of HP restored by your next Waltz.\n-- Actual function: Doubles final Curing Waltz result, makes Healing Waltz AoE from target (10' range)\n-- Obtained: DNC Level 50\n-- Recast Time: 00:05:00\n-- Duration: 00:01:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.dancer.useContradanceAbility(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/convergence.lua"]={["Path"]="scripts/actions/abilities/convergence.lua",["SHA256"]="d6b9d0dfa3716537db8c6980a772b0bf865cafa5be3d375232d5cc968cfb0275",["Text"]="-----------------------------------\n-- Ability: Convergence\n-- Increases the power of your next magical blue magic spell. Limits area of effect to single target.\n-- Obtained: Blue Mage Level 75\n-- Recast Time: 10:00\n-- Duration: 1:00, or until the next eligible blue magic spell is cast.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    xi.job_utils.blue_mage.checkConvergence(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.blue_mage.useConvergence(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/convert.lua"]={["Path"]="scripts/actions/abilities/convert.lua",["SHA256"]="1ec301b79e04fa750bdbd39c804c86d04967c5c9c5415f533e83ae725ce6dc7a",["Text"]="-----------------------------------\n-- Ability: Convert\n-- Swaps current HP with MP.\n-- Obtained: Red Mage Level 40\n-- Recast Time: 10:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:getMP() == 0 then\n        return xi.msg.basic.CANNOT_PERFORM, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    xi.job_utils.red_mage.useConvert(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/cooldown.lua"]={["Path"]="scripts/actions/abilities/cooldown.lua",["SHA256"]="b7306a9559e0ae415b8d5e2e814976f5a37e7ede5c313a6a1935da7cf593c640",["Text"]="-----------------------------------\n-- Ability: Cooldown\n-- Description: Reduces the strain on your automaton.\n-- Obtained: PUP Level 95\n-- Recast Time: 00:05:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.puppetmaster.onAbilityCheckCooldown(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.puppetmaster.onAbilityUseCooldown(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/corsairs_roll.lua"]={["Path"]="scripts/actions/abilities/corsairs_roll.lua",["SHA256"]="b385b276c6eb10ce604a2fe76224882b60f269fb6cf32ebf29c8cde9a34f87b6",["Text"]="-----------------------------------\n-- Ability: Corsair's Roll\n-- Increases the amount of experience points earned by party members within area of effect\n-- Optimal Job: Corsair\n-- Lucky Number: 5\n-- Unlucky Number: 9\n-- Level: 5\n-- Phantom Roll +1 Value: 2\n--\n-- Die Roll    |Exp Bonus%\n-- --------    -----------\n-- 1           |10%\n-- 2           |11%\n-- 3           |11%\n-- 4           |12%\n-- 5           |20%\n-- 6           |13%\n-- 7           |15%\n-- 8           |16%\n-- 9           |8%\n-- 10          |17%\n-- 11          |24%\n-- 12+         |-6%\n--\n-- Bust for Corsair set as subjob is also -6%.\n-- Corsair set as subjob is 7% on Lucky roll (5) and 1% on Unlucky roll (9).\n-- The EXP bonus afforded by Corsair's Roll does not apply within Abyssea.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/counterstance.lua"]={["Path"]="scripts/actions/abilities/counterstance.lua",["SHA256"]="fa92b5d4254dfc96a352b9ba4b0b23abb21858a1911a5061975e73faff7422a0",["Text"]="-----------------------------------\n-- Ability: Counterstance\n-- Increases chance to counter but lowers defense.\n-- Obtained: Monk Level 45\n-- Recast Time: 5:00\n-- Duration: 5:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.monk.useCounterstance(player, target, ability)\nend\n\nreturn abilityObject\n"}};
